package com.agacostays.billing.service.impl;
import com.agacostays.billing.dto.response.InvoiceResponse;import com.agacostays.billing.entity.*;import com.agacostays.billing.enums.InvoiceStatus;import com.agacostays.billing.exception.ResourceNotFoundException;import com.agacostays.billing.mapper.InvoiceMapper;import com.agacostays.billing.repository.*;import com.agacostays.billing.service.InvoiceService;import com.agacostays.billing.storage.InvoiceStorageService;import jakarta.transaction.Transactional;import org.springframework.stereotype.Service;import java.util.UUID;
@Service public class InvoiceServiceImpl implements InvoiceService{private final InvoiceRepository ir;private final BillingRepository br;private final InvoiceMapper im;private final InvoiceStorageService ss;public InvoiceServiceImpl(InvoiceRepository i,BillingRepository b,InvoiceMapper m,InvoiceStorageService s){ir=i;br=b;im=m;ss=s;}@Transactional public InvoiceResponse generate(Long billId){Bill b=br.findById(billId).orElseThrow(()->new ResourceNotFoundException("Bill not found: "+billId));Invoice x=ir.findByBillId(billId).orElse(null);if(x!=null)return im.toResponse(x);String n="AGA-"+billId+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();x=ir.save(Invoice.builder().billId(billId).invoiceNumber(n).invoiceStatus(InvoiceStatus.GENERATED).build());x.setInvoiceUrl("/api/invoices/"+x.getInvoiceId()+"/download");ir.save(x);ss.store(b,n);b.setInvoiceUrl(x.getInvoiceUrl());br.save(b);return im.toResponse(x);}public InvoiceResponse get(Long id){return im.toResponse(ir.findById(id).orElseThrow(()->new ResourceNotFoundException("Invoice not found: "+id)));}public byte[] download(Long id){Invoice i=ir.findById(id).orElseThrow(()->new ResourceNotFoundException("Invoice not found: "+id));return ss.read(i.getInvoiceNumber());}}
